// =========================================================
// D4SnoTypeRegistry implementation
// =========================================================

D4SnoTypeRegistry::D4SnoTypeRegistry() {
    m_types = kTypes;
    m_typeCount = 2915;
    m_fields = kFields;
    m_fieldCount = 19571;
    m_typeNames = kTypeNames;
    m_fieldNames = kFieldNames;
    m_formatMap = kFormatHashMap;
    m_formatMapCount = 130;

    // Build hash lookup table (open addressing)
    m_hashLookup = new u32[kHashBuckets];
    std::memset(m_hashLookup, 0xFF, kHashBuckets * sizeof(u32)); // 0xFFFFFFFF = empty
    for (u32 i = 0; i < m_typeCount; ++i) {
        u32 bucket = m_types[i].hash % kHashBuckets;
        while (m_hashLookup[bucket] != 0xFFFFFFFF) {
            bucket = (bucket + 1) % kHashBuckets;
        }
        m_hashLookup[bucket] = i;
    }
}

const D4SnoTypeRegistry& D4SnoTypeRegistry::instance() {
    static D4SnoTypeRegistry reg;
    return reg;
}

const SnoTypeDef* D4SnoTypeRegistry::findType(u32 typeHash) const {
    u32 bucket = typeHash % kHashBuckets;
    for (;;) {
        u32 idx = m_hashLookup[bucket];
        if (idx == 0xFFFFFFFF)
            return nullptr;
        if (m_types[idx].hash == typeHash)
            return &m_types[idx];
        bucket = (bucket + 1) % kHashBuckets;
    }
}

u32 D4SnoTypeRegistry::typeHashFromKey(u32 formatHash) const {
    // Binary search on the sorted (formatHash, typeHash) array.
    size_t lo = 0, hi = m_formatMapCount;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (m_formatMap[mid].first < formatHash)
            lo = mid + 1;
        else
            hi = mid;
    }
    if (lo < m_formatMapCount && m_formatMap[lo].first == formatHash)
        return m_formatMap[lo].second;
    return 0;
}

const char* D4SnoTypeRegistry::typeName(const SnoTypeDef& def) const {
    // Find index of def in array
    size_t idx = static_cast<size_t>(&def - m_types);
    if (idx < m_typeCount)
        return m_typeNames[idx];
    return "<unknown>";
}

std::span<const SnoFieldDef> D4SnoTypeRegistry::fields(const SnoTypeDef& def) const {
    if (def.fieldsCount == 0)
        return {};
    return {m_fields + def.fieldsOffset, def.fieldsCount};
}

const char* D4SnoTypeRegistry::fieldName(const SnoFieldDef& def) const {
    return m_fieldNames[def.nameIndex];
}

